import{_ as a,c as n,o as p,aM as e}from"./chunks/framework.kKeYZnSg.js";const k=JSON.parse('{"title":"Turborepo","description":"","frontmatter":{"author":"ChatGPT"},"headers":[],"relativePath":"build-tools/monorepo/turborepo.md","filePath":"build-tools/monorepo/turborepo.md","lastUpdated":1787499056000}'),i={name:"build-tools/monorepo/turborepo.md"};function t(l,s,o,r,h,c){return p(),n("div",null,s[0]||(s[0]=[e(`<h1 id="turborepo" tabindex="-1"><a href="https://turborepo.dev/" target="_blank" rel="nofollow noopener noreferrer">Turborepo</a> <a class="header-anchor" href="#turborepo" aria-label="Permalink to &quot;[Turborepo](https://turborepo.dev/)&quot;">​</a></h1><p><a href="https://github.com/zlx01/turborepo-glimpse" target="_blank" rel="nofollow noopener noreferrer">https://github.com/zlx01/turborepo-glimpse</a></p><p>Turborepo 是一个专门面向 <strong>JavaScript / TypeScript 项目的高性能构建系统</strong>，最典型的使用场景就是管理 <strong>Monorepo</strong>。官方现在把它定义为 “high-performance build system”，底层主要用 Rust 实现。(<a href="https://turborepo.com/docs?utm_source=chatgpt.com" target="_blank" rel="nofollow noopener noreferrer">Turborepo</a>)</p><p>你可以把它理解成：</p><blockquote><p><strong>pnpm workspace / npm workspace 负责“把多个 package 放在一个仓库里”，Turborepo 负责“这些 package 的任务该怎么高效执行”。</strong></p></blockquote><p>比如你的项目：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-monorepo/</span></span>
<span class="line"><span>├─ apps/</span></span>
<span class="line"><span>│  ├─ web</span></span>
<span class="line"><span>│  └─ admin</span></span>
<span class="line"><span>├─ packages/</span></span>
<span class="line"><span>│  ├─ ui</span></span>
<span class="line"><span>│  ├─ utils</span></span>
<span class="line"><span>│  └─ eslint-config</span></span>
<span class="line"><span>├─ pnpm-workspace.yaml</span></span>
<span class="line"><span>└─ turbo.json</span></span></code></pre></div><p>这里 <code>pnpm workspace</code> 负责 package 之间的依赖、安装、软链接；而 Turborepo 则负责：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>它会知道类似这样的依赖关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/utils</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>packages/ui</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>apps/web</span></span></code></pre></div><p>所以执行 <code>build</code> 时，Turbo 可以自动按照依赖顺序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>utils build</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ui build</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>web build</span></span></code></pre></div><p>而不是你自己手写：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> utils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>它最核心的价值其实是 <strong>任务调度 + 缓存</strong>。</p><p>例如第一次：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>utils build   2s</span></span>
<span class="line"><span>ui build      3s</span></span>
<span class="line"><span>web build     5s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总计 10s</span></span></code></pre></div><p>第二次代码没变：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>utils build   cache</span></span>
<span class="line"><span>ui build      cache</span></span>
<span class="line"><span>web build     cache</span></span></code></pre></div><p>可能几乎瞬间完成。CI 里尤其有价值。</p><p>除此之外，它还可以识别哪些任务之间没有依赖，然后<strong>并行执行</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/web lint      ──────┐</span></span>
<span class="line"><span>apps/admin lint    ──────┤ 并行</span></span>
<span class="line"><span>packages/ui lint   ──────┘</span></span></code></pre></div><p>Turborepo 本身建立在包管理器的 <strong>Workspaces</strong> 之上，所以它不是 pnpm/npm/yarn workspace 的替代品，而是在其上增加任务编排和构建优化。(<a href="https://turborepo.com/docs/crafting-your-repository/structuring-a-repository?utm_source=chatgpt.com" target="_blank" rel="nofollow noopener noreferrer">Turborepo</a>)</p><p>通常会有一个：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://turborepo.com/schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;outputs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dist/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;lint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>其中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>^build</span></span></code></pre></div><p>大概表示：</p><blockquote><p>当前 package build 之前，先执行它依赖的 package 的 build。</p></blockquote><p>所以比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>web</span></span>
<span class="line"><span> ↓ depends on</span></span>
<span class="line"><span>ui</span></span>
<span class="line"><span> ↓ depends on</span></span>
<span class="line"><span>utils</span></span></code></pre></div><p>Turbo 会自己计算任务图。</p><h3 id="它和-nx-lerna-的关系" tabindex="-1">它和 Nx / Lerna 的关系 <a class="header-anchor" href="#它和-nx-lerna-的关系" aria-label="Permalink to &quot;它和 Nx / Lerna 的关系&quot;">​</a></h3><p>可以大致这么看：</p><table tabindex="0"><thead><tr><th>工具</th><th>核心定位</th></tr></thead><tbody><tr><td>pnpm workspace</td><td>Monorepo 包管理</td></tr><tr><td>npm/yarn workspace</td><td>Monorepo 包管理</td></tr><tr><td><strong>Turborepo</strong></td><td>Monorepo 任务调度、缓存、构建加速</td></tr><tr><td>Nx</td><td>更完整的 Monorepo 工程平台</td></tr><tr><td>Lerna</td><td>老牌 Monorepo package 管理 / 发布工具</td></tr></tbody></table><p>所以 <strong>Turbo 相比 Nx 更轻</strong>。</p><p>Nx 更像：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>包管理</span></span>
<span class="line"><span>项目生成器</span></span>
<span class="line"><span>任务调度</span></span>
<span class="line"><span>缓存</span></span>
<span class="line"><span>依赖图</span></span>
<span class="line"><span>插件体系</span></span>
<span class="line"><span>代码生成</span></span>
<span class="line"><span>affected 分析</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Turbo 更聚焦：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务依赖</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>并行执行</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>缓存</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>CI 加速</span></span></code></pre></div><h3 id="一个很好记的类比" tabindex="-1">一个很好记的类比 <a class="header-anchor" href="#一个很好记的类比" aria-label="Permalink to &quot;一个很好记的类比&quot;">​</a></h3><p>如果把：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vite / Rspack / Webpack</span></span></code></pre></div><p>看成：</p><blockquote><p><strong>单个项目怎么 build</strong></p></blockquote><p>那么：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Turborepo</span></span></code></pre></div><p>解决的是：</p><blockquote><p><strong>一个仓库里有 20 个项目/package，到底哪些需要 build、先 build 谁、哪些可以并行、哪些可以直接读缓存。</strong></p></blockquote><p>因此它<strong>不是 Bundler</strong>，不会替代 Vite / Webpack / Rspack。</p><p>你的项目完全可能是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Turborepo</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>├─ apps/web     → Vite</span></span>
<span class="line"><span>├─ apps/admin   → Rspack</span></span>
<span class="line"><span>├─ packages/ui  → tsup</span></span>
<span class="line"><span>└─ packages/sdk → tsc</span></span></code></pre></div><p>一句话总结：</p><p><strong>Turborepo = 给 JS/TS Monorepo 做任务编排和缓存加速的工具。</strong> 对前端工程视角来说，可以先把它归类为 <strong>Monorepo Build System / Task Runner</strong>，而不是 Compiler 或 Bundler。(<a href="https://turborepo.com/docs?utm_source=chatgpt.com" target="_blank" rel="nofollow noopener noreferrer">Turborepo</a>)</p>`,55)]))}const u=a(i,[["render",t]]);export{k as __pageData,u as default};
